from pathlib import Path
import json,base64,subprocess,urllib.request
base=Path('/home/operator/qwen38-5090/optimization-runs');r=base/'client-smoke-015';assert not r.exists();r.mkdir()
pid=json.loads((base/'exp012-block6/server-pid.json').read_text());p=Path('/proc')/str(pid['pid'])
assert p.exists() and (p/'stat').read_text().split()[21]==pid['stat'].split()[21]
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()==pid['boot_id']
print('PROCESS',pid['pid'],(p/'cmdline').read_bytes().replace(b'\0',b' ').decode()[:200])
(r/'benchmark_stream.py').write_bytes(base64.b64decode(''))
(r/'cases.json').write_text(json.dumps({'repetitions':1,'cases':[{'name':'openai-wire-smoke','payload':{'messages':[{'role':'user','content':'Compute 17+25. Think briefly and then answer.'}],'temperature':0,'top_p':1,'max_tokens':128}}]}))
p=subprocess.run(['python3',str(r/'benchmark_stream.py'),'--protocol','openai','--url','http://127.0.0.1:34731','--expected-model','qwen-normal-exp012','--manifest',str(r/'cases.json'),'--output',str(r/'results.jsonl')],env={'PATH':'/usr/bin:/bin','HOME':str(r),'TMPDIR':str(r),'PYTHONDONTWRITEBYTECODE':'1'},capture_output=True,text=True,timeout=180)
print('EXIT',p.returncode,p.stderr)
for line in (r/'results.jsonl').read_text().splitlines():
 d=json.loads(line);d.pop('events',None);d.pop('declared_settings',None);print(json.dumps(d))
